window.RP_SESSION={"id":"S-e10e3b5ae767","messages":[{"id":"RP-II-0101938","time":"2026-05-17T03:02:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"레마는 나무에 도끼를 내려치지만 박히기만 하고 쪼개지질 않는다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0101939","time":"2026-05-17T03:02:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"괜찮아. 첫 일격이 튕겨나지 않고 금만 갔다면...","characters":["P-fec1db60d51e"]},{"id":"RP-II-0101940","time":"2026-05-17T03:02:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!힘+2","characters":["P-fec1db60d51e"]},{"id":"RP-II-0101941","time":"2026-05-17T03:02:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 힘 판정 :\n[5] + [1] + [2] = [8]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-II-0101942","time":"2026-05-17T03:03:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"다시 한 번 내려치자 나무가 반으로 쩍 갈라진다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0101943","time":"2026-05-17T03:03:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-fec1db60d51e"]},{"id":"RP-II-0101944","time":"2026-05-17T03:03:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 힘 판정 :\n[10] + [1] = [11]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-II-0101945","time":"2026-05-17T03:03:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"또 다시 도끼를 나무에 휘둘러서 쪼개 장작에 쓰기 좋은 사이즈로 만들고 있는 레마.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0101946","time":"2026-05-17T03:03:00+09:00","room":"RP II","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"레마! 안 자고 여기서 뭐해?\"\n레마 발견하고는 다가간다.","characters":["P-5401fadc6bc3"]},{"id":"RP-II-0101947","time":"2026-05-17T03:04:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 멜리아! 길드에서 쓰, 쓰는 장작을 만들고 있었지. 장작은 마, 많을수록 좋잖아! 따듯하고 마, 말야. \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0101948","time":"2026-05-17T03:05:00+09:00","room":"RP II","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"그렇지! 근데 이제 여름이니까, 그렇게 많이는 필요 없을 거야. 적당히 해둬!\"","characters":["P-5401fadc6bc3"]},{"id":"RP-II-0101949","time":"2026-05-17T03:07:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 여름이라 마, 많이 필요 없다니. 불은 모, 모든 곳에 쓰이는걸. 개울 물은 어, 언제나 끓여야 먹을 수 있고, 샐러드를 하, 할게 아니라면 늘 불이 피, 필요하지. 그리고 난방이나 요리가 아, 아니더라도 장작은 필요해! \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0101950","time":"2026-05-17T03:08:00+09:00","room":"RP II","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"그래도, 너무 과하면 오히려 장작 창고가 미어터질걸? 그러니까 적당히 해두는 게 좋을 거라고 생각해!\"","characters":["P-5401fadc6bc3"]},{"id":"RP-II-0101951","time":"2026-05-17T03:09:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 좋아. 항상 과, 과유불급이니까. \"\n\n장작 패기를 멈추고.\n\n\" 조금은 우리가 쓰, 쓸까? \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0101952","time":"2026-05-17T03:10:00+09:00","room":"RP II","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"좋아! 오늘도 레마가 요리해 줄 거야?\"","characters":["P-5401fadc6bc3"]},{"id":"RP-II-0101953","time":"2026-05-17T03:11:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 무, 물론이지! 마침 닭고기가 있는데... \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0101954","time":"2026-05-17T03:11:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!모닥불","characters":["P-fec1db60d51e"]},{"id":"RP-II-0101955","time":"2026-05-17T03:11:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"모닥불에 불씨가 옮겨 붙습니다.\n따뜻한 온기가 피어오릅니다.\n\n ♩ https://youtu.be/3GNyTB6p6i0?si=4L6Rg34M-gtWRqUj","characters":[]},{"id":"RP-II-0101956","time":"2026-05-17T03:11:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"모닥불을 켜고 닭고기를 정육하고 소스를 발라 굽기 시작한다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0101957","time":"2026-05-17T03:11:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-fec1db60d51e"]},{"id":"RP-II-0101958","time":"2026-05-17T03:12:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 지능 판정 :\n[8] + [1] = [9]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-II-0101959","time":"2026-05-17T03:12:00+09:00","room":"RP II","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"오늘도 기대할게!\"","characters":["P-5401fadc6bc3"]},{"id":"RP-II-0101960","time":"2026-05-17T03:12:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"노릇하게 익어가는 닭고기.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0101961","time":"2026-05-17T03:13:00+09:00","room":"RP II","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"잘한다!\"","characters":["P-5401fadc6bc3"]},{"id":"RP-II-0101962","time":"2026-05-17T03:13:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"달걀을 생산하는 젊은 암탉을 막 도축하진 않을테니 필시 사이즈가 큰 노계겠지만, 질긴 것 정도는 중세 사람들에게 큰 문제가 될리가.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0101963","time":"2026-05-17T03:14:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"육향 가득, 적절한 간과 향신료 농도의 붉은 양념이 발린 닭 통구이.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0101964","time":"2026-05-17T03:14:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-fec1db60d51e"]},{"id":"RP-II-0101965","time":"2026-05-17T03:14:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"완성.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0101966","time":"2026-05-17T03:14:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"구이가 아닌 것 같다구요? 어쩌라구이.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0101967","time":"2026-05-17T03:15:00+09:00","room":"RP II","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"와 맛있겠다!\"","characters":["P-5401fadc6bc3"]},{"id":"RP-II-0101968","time":"2026-05-17T03:21:00+09:00","room":"RP II","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-5401fadc6bc3"]},{"id":"RP-II-0101969","time":"2026-05-17T03:21:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]},{"id":"RP-II-0101970","time":"2026-05-17T13:41:00+09:00","room":"RP II","name":"스텔라 스타라이트","profile":"스텔라 스타라이트","identity":"unresolved","type":"dialogue","body":"그냥 치킨 먹고 있는거 자랑하려고 한 것 아니야?!","characters":[]},{"id":"RP-II-0101971","time":"2026-05-17T13:41:00+09:00","room":"RP II","name":"조니","profile":"조니","identity":"unresolved","type":"dialogue","body":"팩트)다","characters":[]}]};
